// ?wÅf????O?ÅÒ?t?B?b?N?n?Åg?h?????AÅg??Å˜?O?ÅÒ?t?B?b?N?f?[?^????Åhh?Å˜?????????O?ÅÒ?t?B?b?N?n?Åg?h??( DerivationGraph ??Åhh?Å˜?????n?Åg?h???ALoadDivGraph Åg??????????????????????Åh???n?Åg?h?? )????Ågx??????????
extern	int NS_DeleteSharingGraph( int GrHandle )
{
	IMAGEDATA_ORIG *Orig ;
	IMAGEDATA *Image, **TmpImage ;
	bool BreakFlag ;

	// ?G?ÅÒ?[Åh?Åf?
	if( GRAPHCHK( GrHandle, Image ) )
		return -1 ;

	// Åg??Å˜?O?ÅÒ?t?B?b?N?f?[?^????Åhh?Å˜?????????n?Åg?h????ÅeS??????????
	Orig = Image->Orig ;
	BreakFlag = false ;
	for( TmpImage = ( IMAGEDATA ** )&HandleManageArray[ DX_HANDLETYPE_GRAPH ].Handle[ HandleManageArray[ DX_HANDLETYPE_GRAPH ].AreaMin ] ; ; TmpImage ++ )
	{
		if( *TmpImage == NULL ) continue ;

		if( ( *TmpImage )->Orig == Orig )
		{
			BreakFlag = Orig->RefCount == 1 ;
			SubHandle( ( *TmpImage )->HandleInfo.Handle, GetASyncLoadFlag(), FALSE ) ;
			if( BreakFlag ) break ;
		}
	}

	// ?I??
	return 0 ;
}

