		VPosD[ 3 ][ 2 ][ 1 ].y = ( V4Line[ 2 ].x * V3Line[ 1 ].z - V4Line[ 2 ].z * V3Line[ 1 ].x ) / ( V4Line[ 2 ].y * V3Line[ 1 ].x - V4Line[ 2 ].x * V3Line[ 1 ].y ) ;
