		VPosD[ 3 ][ 3 ][ 3 ].y = ( V4Line[ 3 ].x * V3Line[ 3 ].z - V4Line[ 3 ].z * V3Line[ 3 ].x ) / ( V4Line[ 3 ].y * V3Line[ 3 ].x - V4Line[ 3 ].x * V3Line[ 3 ].y ) ;

