			Vertex[ 2 ].u = Line_Out_UV[ 1 ] ;	Vertex[ 2 ].v = Line_Out_UV[ 1 ] ;
			Vertex[ 3 ].u = Line_Out_UV[ 1 ] ;	Vertex[ 3 ].v = Line_Out_UV[ 1 ] ;

			Vertex += 4 ;

