			Vertex[ 2 ].u = Line_In_UV[ 1 ] ;	Vertex[ 2 ].v = Line_In_UV[ 1 ] ;
			Vertex[ 3 ].u = Line_In_UV[ 0 ] ;	Vertex[ 3 ].v = Line_In_UV[ 1 ] ;

