			Vertex[ 0 ].y = VPosD[ n ][ 3 ][ 0 ].y ;
			Vertex[ 1 ].x = VPosD[ i ][ 0 ][ 3 ].x ;
			Vertex[ 1 ].y = VPosD[ i ][ 0 ][ 3 ].y ;
