// ?p???????l?p?`???`ÅÒ?????( ?A?Åg?`?G?C???A?X?t?? )
extern int NS_DrawRoundRectAA( float x1, float y1, float x2, float y2, float rx, float ry, int posnum, unsigned int Color, int FillFlag, float LineThickness )
{
	float Temp ;
	float DrawSizeX ;
	float DrawSizeY ;

	if( rx <= 0.0f )
	{
		rx = 1.0f ;
	}

	if( ry <= 0.0f )
	{
		ry = 1.0f ;
	}

	if( x2 < x1 )
	{
		Temp = x1 ;
		x1 = x2 ;
		x2 = Temp ;
	}

	if( y2 < y1 )
	{
		Temp = y1 ;
		y1 = y2 ;
		y2 = Temp ;
	}

	DrawSizeX = x2 - x1 ;
	DrawSizeY = y2 - y1 ;

	if( rx * 2.0f > DrawSizeX )
	{
		rx = DrawSizeX / 2.0f ;
	}

	if( ry * 2 > DrawSizeY )
	{
		ry = DrawSizeY / 2.0f ;
	}

	if( posnum < 2 )
	{
		posnum = 2 ;
	}
	else
	if( posnum > CIRCLE_MAX_POSNUM / 4 )
	{
		posnum = CIRCLE_MAX_POSNUM / 4 ;
	}

	if( FillFlag == FALSE )
	{
		return DrawRoundRectLineAA( x1, y1, x2, y2, rx, ry, posnum, Color, LineThickness ) ;
	}
	else
	{
		return DrawRoundRectFillAA( x1, y1, x2, y2, rx, ry, posnum, Color ) ;
	}
}

