// ?O?ÅÒ?t?B?b?N??ÅÒ?Åg]?`ÅÒ??Q
extern	int NS_DrawRotaGraph2F( float xf, float yf, float cxf, float cyf, double ExtRate, double Angle, int GrHandle, int TransFlag, int ReverseXFlag, int ReverseYFlag )
{
	int w, h ;

	NS_GetGraphSize( GrHandle, &w,&h ) ;

	if( Angle == 0.0 )
	{
		if( ExtRate == 1.0 )
		{
			return NS_DrawReverseGraphF( xf - cxf, yf - cyf, GrHandle, TransFlag, ReverseXFlag, ReverseYFlag ) ;
		}
		else
		{
			float numF[ 4 ] ;

			numF[ 0 ] = xf - ( cxf * ( float )ExtRate ) ;
			numF[ 1 ] = yf - ( cyf * ( float )ExtRate ) ;
			numF[ 2 ] = numF[ 0 ] + ( w * ( float )ExtRate ) ;
			numF[ 3 ] = numF[ 1 ] + ( h * ( float )ExtRate ) ;
			if( ReverseXFlag )
			{
				float d ;

				d = numF[ 0 ] ; numF[ 0 ] = numF[ 2 ] ; numF[ 2 ] = d ;
			}
			if( ReverseYFlag )
			{
				float d ;

				d = numF[ 1 ] ; numF[ 1 ] = numF[ 3 ] ; numF[ 3 ] = d ;
			}
			return NS_DrawExtendGraphF( numF[0], numF[1],
										numF[2], numF[3],
										 GrHandle, TransFlag ) ;
		}
	}
	else
	{
		float dcx, dcy ;
		float Sin, Cos ;
		float bcx, bcy ;

		bcx = ( -cxf + ( float )w * 0.5F ) * ( float )ExtRate ;
		bcy = ( -cyf + ( float )h * 0.5F ) * ( float )ExtRate ;

		_SINCOS_PLATFORM( ( float )Angle, &Sin, &Cos ) ;
		dcx = bcx * Cos - bcy * Sin ;
		dcy = bcx * Sin + bcy * Cos ;

		return NS_DrawRotaGraphF( xf + dcx, yf + dcy, ExtRate, Angle, GrHandle, TransFlag, ReverseXFlag, ReverseYFlag ) ; 
	}
}


// ?O?ÅÒ?t?B?b?N??ÅÒ?Åg]?`ÅÒ??R
static int DrawRotaGraph3F_Base( float xf, float yf, float cxf, float cyf, double ExtRateX, double ExtRateY, double Angle, int GrHandle, int TransFlag, int ReverseXFlag, int ReverseYFlag, int IntFlag )
{
	int w, h ;

	NS_GetGraphSize( GrHandle, &w,&h ) ;

	if( Angle == 0.0 )
	{
		if( ExtRateX == 1.0 && ExtRateY == 1.0 )
		{
			return NS_DrawReverseGraphF( xf - cxf, yf - cyf, GrHandle, TransFlag, ReverseXFlag, ReverseYFlag ) ;
		}
		else
		{
			float numF[ 4 ] ;

			numF[ 0 ] = xf - ( cxf * ( float )ExtRateX ) ;
			numF[ 1 ] = yf - ( cyf * ( float )ExtRateY ) ;
			numF[ 2 ] = numF[ 0 ] + ( w * ( float )ExtRateX ) ;
			numF[ 3 ] = numF[ 1 ] + ( h * ( float )ExtRateY ) ;
			if( ReverseXFlag )
			{
				float d ;

				d = numF[ 0 ] ; numF[ 0 ] = numF[ 2 ] ; numF[ 2 ] = d ;
			}
			if( ReverseYFlag )
			{
				float d ;

				d = numF[ 1 ] ; numF[ 1 ] = numF[ 3 ] ; numF[ 3 ] = d ;
			}
			return NS_DrawExtendGraphF( numF[0], numF[1],
										numF[2], numF[3],
										 GrHandle, TransFlag ) ;
		}
	}
	else
	{
		if( ExtRateX == 1.0 && ExtRateY == 1.0 )
		{
			float dcx, dcy ;
			float Sin, Cos ;
			float bcx, bcy ;

			bcx = ( -cxf + ( float )w * 0.5F ) ;
			bcy = ( -cyf + ( float )h * 0.5F ) ;

			_SINCOS_PLATFORM( ( float )Angle, &Sin, &Cos ) ;
			dcx = bcx * Cos - bcy * Sin ;
			dcy = bcx * Sin + bcy * Cos ;

			return NS_DrawRotaGraphF( xf + dcx, yf + dcy, 1.0, Angle, GrHandle, TransFlag, ReverseXFlag, ReverseYFlag ) ; 
		}
		else
		{
			float xx[ 4 ], yy[ 4 ] ;
			float xxt[ 4 ], yyt[ 4 ] ;
			int i ;
			float SinF, CosF ;

			xxt[0] = (   - cxf )	* ( float )ExtRateX ;	yyt[0] = (   - cyf )	* ( float )ExtRateY ;
			xxt[1] = ( w - cxf )	* ( float )ExtRateX ;	yyt[1] = yyt[0] ;
			xxt[2] = xxt[0] ;								yyt[2] = ( h - cyf )	* ( float )ExtRateY ;
			xxt[3] = xxt[1] ;								yyt[3] = yyt[2] ;

			_SINCOS_PLATFORM( ( float )Angle, &SinF, &CosF ) ;
			for( i = 0 ; i < 4 ; i ++ )
			{
				xx[ i ] = xxt[ i ] * CosF - yyt[ i ] * SinF + xf ;
				yy[ i ] = xxt[ i ] * SinF + yyt[ i ] * CosF + yf ;
			}

			if( ReverseXFlag && ReverseYFlag )
			{
				float d ;

				d = xx[ 0 ] ; xx[ 0 ] = xx[ 3 ] ; xx[ 3 ] = d ;
				d = xx[ 1 ] ; xx[ 1 ] = xx[ 2 ] ; xx[ 2 ] = d ;
				d = yy[ 0 ] ; yy[ 0 ] = yy[ 3 ] ; yy[ 3 ] = d ;
				d = yy[ 1 ] ; yy[ 1 ] = yy[ 2 ] ; yy[ 2 ] = d ;
			}
			else
			if( ReverseXFlag )
			{
				float d ;

				d = xx[ 0 ] ; xx[ 0 ] = xx[ 1 ] ; xx[ 1 ] = d ;
				d = xx[ 2 ] ; xx[ 2 ] = xx[ 3 ] ; xx[ 3 ] = d ;
				d = yy[ 0 ] ; yy[ 0 ] = yy[ 1 ] ; yy[ 1 ] = d ;
				d = yy[ 2 ] ; yy[ 2 ] = yy[ 3 ] ; yy[ 3 ] = d ;
			}
			else
			if( ReverseYFlag )
			{
				float d ;

				d = xx[ 0 ] ; xx[ 0 ] = xx[ 2 ] ; xx[ 2 ] = d ;
				d = xx[ 1 ] ; xx[ 1 ] = xx[ 3 ] ; xx[ 3 ] = d ;
				d = yy[ 0 ] ; yy[ 0 ] = yy[ 2 ] ; yy[ 2 ] = d ;
				d = yy[ 1 ] ; yy[ 1 ] = yy[ 3 ] ; yy[ 3 ] = d ;
			}

			if( IntFlag && GSYS.HardInfo.DrawFloatCoordType == DX_DRAWFLOATCOORDTYPE_DIRECT3D9 )
			{
				xx[0] -= 0.5f ;
				yy[0] -= 0.5f ;
				xx[1] -= 0.5f ;
				yy[1] -= 0.5f ;
				xx[3] -= 0.5f ;
				yy[3] -= 0.5f ;
				xx[2] -= 0.5f ;
				yy[2] -= 0.5f ;
			}

			return Graphics_Draw_ModiGraphFBase( xx[0], yy[0], xx[1], yy[1], xx[3], yy[3], xx[2], yy[2], GrHandle, TransFlag, TRUE ) ;
		}
	}
}

