// DrawCircleGauge ???Åh?????????Åh
static void DrawCircleGaugePolygon(
	int GraphHandle,
	float CenterX,
	float CenterY,
	VECTOR *pVector,
	float SizeR,
	float UScale,
	float VScale,
	float UStart,
	float VStart,
	int ReverseX,
	int ReverseY
)
{
	int i ;
	VERTEX vert[ 3 ] ;
	float AdjustPosition ;

	AdjustPosition = GSYS.HardInfo.DrawFloatCoordType == DX_DRAWFLOATCOORDTYPE_DIRECT3D9 ? 0.5f : 0.0f ;
	
	for( i = 0; i < 3; i ++ )
	{
		vert[i].x = ( ReverseX ? -pVector[i].x : pVector[i].x ) + CenterX + AdjustPosition ;
		vert[i].y = ( ReverseY ? -pVector[i].y : pVector[i].y ) + CenterY + AdjustPosition ;
		vert[i].u = ( pVector[i].x * SizeR + 0.5f ) * UScale + UStart ;
		vert[i].v = ( pVector[i].y * SizeR + 0.5f ) * VScale + VStart ;
		vert[i].b = 255 ;
		vert[i].g = 255 ;
		vert[i].r = 255 ;
		vert[i].a = 255 ;
	}
	NS_DrawPolygon( vert, 1, GraphHandle, TRUE, FALSE );
}

// ÅÒ~?O?ÅÒ?tÅgI???`ÅÒ????s??
int NS_DrawCircleGauge( int CenterX, int CenterY, double Percent, int GrHandle, double StartPercent , double Scale, int ReverseX, int ReverseY )
{
	VECTOR vertex[3] ;
	VECTOR position[4] ;
	VECTOR positionR ;
	VECTOR positionR2 ;
	float radian ;
	float radian2 ;
	float length ;
	float Sin ;
	float Cos ;
	float CenterXF ;
	float CenterYF ;
	float SizeR ;
	int SizeX ;
	int SizeY ;
	int i ;
	float StartRad ;
	float EndRad ;
	IMAGEDATA *Image ;
	float UScale ;
	float VScale ;
	float UStart ;
	float VStart ;
	RECT DrawRect ;
	RECT GaugeDrawRect ;
	int CullMode ;

	Image = Graphics_Image_GetData( GrHandle ) ;
	if( Image == NULL )
	{
		return -1 ;
	}

	// ?J???Åg?O????????Åf?
	CullMode = NS_GetUseBackCulling() ;
	NS_SetUseBackCulling( DX_CULLING_NONE ) ;

	if( Image->Orig->FormatDesc.TextureFlag )
	{
		UStart = ( float )Image->Hard.Draw[ 0 ].UsePosXF / Image->Hard.Draw[ 0 ].Tex->TexWidth ;
		VStart = ( float )Image->Hard.Draw[ 0 ].UsePosYF / Image->Hard.Draw[ 0 ].Tex->TexHeight ;
		UScale = ( float )Image->WidthF                  / Image->Hard.Draw[ 0 ].Tex->TexWidth ;
		VScale = ( float )Image->HeightF                 / Image->Hard.Draw[ 0 ].Tex->TexHeight ;
	}
	else
	{
		UScale = 1.0f ;
		VScale = 1.0f ;
		UStart = 0.0f ;
		VStart = 0.0f ;
	}

	if( StartPercent > 200.0 )
	{
		StartPercent = 200.0 ;
	}
	else
	if( StartPercent < -100.0 )
	{
		StartPercent = -100.0 ;
	}

	if( Percent > 200.0 )
	{
		Percent = 200.0 ;
	}
	else
	if( Percent < -100.0 )
	{
		Percent = -100.0 ;
	}

	if( Percent - StartPercent > 100.0 )
	{
		StartPercent = 0.0 ;
		Percent = 100.0 ;
	}

	if( StartPercent == Percent ||
		StartPercent > Percent )
	{
		return 0 ;
	}

	NS_GetGraphSize( GrHandle, &SizeX, &SizeY );

	radian   = ( float )( Percent      * 2 * DX_PI / 100.0 );
	radian2  = ( float )( StartPercent * 2 * DX_PI / 100.0 );
	length   = ( float )( SizeX * Scale * 0.75f ) ;
	CenterXF = ( float )CenterX;
	CenterYF = ( float )CenterY;
	SizeR    = ( float )( 1.0f / ( SizeX * Scale ) ) ;

	vertex[0].x = 0.0f;
	vertex[0].y = 0.0f;
	vertex[1] = vertex[0];
	vertex[2] = vertex[0];

	position[0].x = 0.0f;
	position[0].y = -length;

	position[1].x = length;
	position[1].y = 0.0f;

	position[2].x = 0.0f;
	position[2].y = length;

	position[3].x = -length;
	position[3].y = 0.0f;

	_SINCOS_PLATFORM( radian2 - DX_PI_F * 0.5f, &Sin, &Cos ) ;
	positionR2.x = Cos * length;
	positionR2.y = Sin * length;

	_SINCOS_PLATFORM( radian - DX_PI_F * 0.5f, &Sin, &Cos ) ;
	positionR.x = Cos * length;
	positionR.y = Sin * length;

	DrawRect = GSYS.DrawSetting.DrawArea ;
	if( Scale != 1.0 )
	{
		GaugeDrawRect.left   = CenterX - _DTOL( SizeX * Scale ) / 2 - 1 ;
		GaugeDrawRect.top    = CenterY - _DTOL( SizeY * Scale ) / 2 - 1 ;
		GaugeDrawRect.right  = CenterX + _DTOL( SizeX * Scale ) / 2 + 1 ;
		GaugeDrawRect.bottom = CenterY + _DTOL( SizeY * Scale ) / 2 + 1 ;
	}
	else
	{
		GaugeDrawRect.left   = CenterX - SizeX / 2 ;
		GaugeDrawRect.top    = CenterY - SizeY / 2 ;
		GaugeDrawRect.right  = CenterX + SizeX / 2 ;
		GaugeDrawRect.bottom = CenterY + SizeY / 2 ;
	}
	RectClipping_Inline( &GaugeDrawRect, &DrawRect ) ;
	NS_SetDrawArea( GaugeDrawRect.left, GaugeDrawRect.top, GaugeDrawRect.right, GaugeDrawRect.bottom ) ; 

	// 90Ågx??Åg??`ÅÒ?
	for( i = 0 ; i < 12 ; i ++ )
	{
		StartRad = DX_PI_F * 0.5f * ( i - 4 ) ;
		EndRad   = DX_PI_F * 0.5f * ( i - 4 + 1 ) ;

		if( ( radian2 >= StartRad && radian2 <= EndRad ) || ( StartRad >= radian2 && StartRad <= radian ) )
		{
			vertex[1] = radian2 <= StartRad ? position[ i         % 4 ] : positionR2;
			vertex[2] = radian  >= EndRad   ? position[ ( i + 1 ) % 4 ] : positionR;
			DrawCircleGaugePolygon( GrHandle, CenterXF, CenterYF, vertex, SizeR, UScale, VScale, UStart, VStart, ReverseX, ReverseY );
		}
	}

	// ?J???Åg?O??Åf???????????
	NS_SetUseBackCulling( CullMode ) ;

	// ?`ÅÒ?ÅÒ?Åh\Åh?????????????
	NS_SetDrawArea( DrawRect.left, DrawRect.top, DrawRect.right, DrawRect.bottom ) ;

	// ?I??
	return 0;
}

