// ?wÅf????W???F????Åg?????
extern unsigned int NS_GetPixelDX( int x, int y )
{
	unsigned int Ret = 0xffffffff ;

	// ?`ÅÒ????W?`?F?b?N
	if( x < 0 || y < 0 || x >= GSYS.DrawSetting.DrawSizeX || y >= GSYS.DrawSetting.DrawSizeY ) return 0xffffffff ;

	// ?n?[?h?E?G?A?@Åh\???g?p????????????????????????
	if( GSYS.Setting.ValidHardware && GSYS.Screen.UserScreenImagePixelFormatMatchSoftRenderMode == FALSE )
	{
		// ?n?[?h?E?F?A???g?p???????Åˆ

		Ret = Graphics_Hardware_GetPixel_PF( x, y ) ;
	}
	else
	{
		MEMIMG    *Img ;
		IMAGEDATA *Image ;

		// ?n?[?h?E?F?A???g?p?????????Åˆ

		// ?G?ÅÒ?[Åh?Åf?
		if( GRAPHCHKFULL( GSYS.DrawSetting.TargetScreen[ 0 ], Image ) )
			Image = NULL ;

		// ?`ÅÒ?????????????????????
		if( Image )
		{
			Img = &Image->Soft.MemImg ;
		}
		else
		{
			Img = &GSYS.SoftRender.MainBufferMemImg ;
		}

		switch( GSYS.Screen.MainScreenColorBitDepth )
		{
		case 16 : Ret = *( (  WORD * )( ( char * )Img->UseImage + 2 * x + Img->Base->Pitch * y ) ) ; break ;
		case 32 : Ret = *( ( DWORD * )( ( char * )Img->UseImage + 4 * x + Img->Base->Pitch * y ) ) ; break ;
		}
	}

	// ?I??
	return Ret ;
}

// ?wÅf????W???F????Åg?????( float?^ )
extern COLOR_F NS_GetPixelF( int x, int y )
{
	// ?`ÅÒ????W?`?F?b?N
	if( x < 0 || y < 0 || x >= GSYS.DrawSetting.DrawSizeX || y >= GSYS.DrawSetting.DrawSizeY )
	{
		return NS_GetColorF( -1.0f, -1.0f, -1.0f, -1.0f ) ;
	}

	// ?n?[?h?E?G?A?@Åh\???g?p????????????????????????
	if( GSYS.Setting.ValidHardware && GSYS.Screen.UserScreenImagePixelFormatMatchSoftRenderMode == FALSE )
	{
		// ?n?[?h?E?F?A???g?p???????Åˆ
		return Graphics_Hardware_GetPixelF_PF( x, y ) ;
	}
	else
	{
		// ?n?[?h?E?F?A???g?p?????????Åˆ
		unsigned int Color = NS_GetPixelDX( x, y ) ;
		COLOR_F Result ;
		int ri, gi, bi, ai ;
		COLORDATA *ColorData = GetMemImgColorData( GSYS.Screen.MainScreenColorBitDepth == 16 ? 0 : 1, FALSE, FALSE ) ;

		NS_GetColor5( ColorData, Color, &ri, &gi, &bi, &ai ) ;

		Result.r = ( float )ri / 255.0f ;
		Result.g = ( float )gi / 255.0f ;
		Result.b = ( float )bi / 255.0f ;
		Result.a = ( float )ai / 255.0f ;
		return Result ;
	}
}

