// ?wÅf??????`???????????????f?B?X?v???C??????
extern const GRAPHICSSYS_DISPLAYINFO *Graphics_GetRectMatchDisplayInfo( const RECT *Rect )
{
	int i ;
	int MaxMatchIndex = -1 ;
	int MaxMatchAreaSize = 0 ;
	GRAPHICSSYS_DISPLAYINFO *DisplayInfo ;

	if( GSYS.Screen.DisplayInfo == NULL )
	{
		return NULL ;
	}

	DisplayInfo = GSYS.Screen.DisplayInfo ;
	for( i = 0 ; i < GSYS.Screen.DisplayNum ; i ++, DisplayInfo ++ )
	{
		int MatchWidth = 0 ;
		int MatchHeight = 0 ;

		if( Rect->left <= DisplayInfo->DesktopRect.left && DisplayInfo->DesktopRect.left < Rect->right )
		{
			MatchWidth = ( DisplayInfo->DesktopRect.right < Rect->right ? DisplayInfo->DesktopRect.right : Rect->right ) - DisplayInfo->DesktopRect.left ;
		}
		else
		if( DisplayInfo->DesktopRect.left <= Rect->left && Rect->left < DisplayInfo->DesktopRect.right )
		{
			MatchWidth = ( DisplayInfo->DesktopRect.right < Rect->right ? DisplayInfo->DesktopRect.right : Rect->right ) - Rect->left ;
		}
		else
		{
			continue ;
		}

		if( Rect->top <= DisplayInfo->DesktopRect.top && DisplayInfo->DesktopRect.top < Rect->bottom )
		{
			MatchHeight = ( DisplayInfo->DesktopRect.bottom < Rect->bottom ? DisplayInfo->DesktopRect.bottom : Rect->bottom ) - DisplayInfo->DesktopRect.top ;
		}
		else
		if( DisplayInfo->DesktopRect.top <= Rect->top && Rect->top < DisplayInfo->DesktopRect.bottom )
		{
			MatchHeight = ( DisplayInfo->DesktopRect.bottom < Rect->bottom ? DisplayInfo->DesktopRect.bottom : Rect->bottom ) - Rect->top ;
		}
		else
		{
			continue ;
		}

		if( MaxMatchIndex == -1 || MatchWidth * MatchHeight > MaxMatchAreaSize )
		{
			MaxMatchIndex = i ;
			MaxMatchAreaSize = MatchWidth * MatchHeight ;
		}
	}

	return MaxMatchIndex < 0 ? NULL : &GSYS.Screen.DisplayInfo[ MaxMatchIndex ] ;
}

// SetUserScreenImage ???wÅf??????s?N?Z???t?H?[?}?b?g?? COLORDATA ????Åg?????
extern COLORDATA *Graphics_Screen_UserScreenPixelFormatColorData( int PixelFormat /* DX_USER_SCREEN_PIXEL_FORMAT_R5G6B5 Åg? */ )
{
	volatile static int InitializeFlag = FALSE ;
	static COLORDATA R5G6B5_ColorData ;
	static COLORDATA R5G5B5X1_ColorData ;
	static COLORDATA X1R5G5B5_ColorData ;
	static COLORDATA X8B8G8R8_ColorData ;
	static COLORDATA X8R8G8B8_ColorData ;

	if( InitializeFlag == FALSE )
	{
		NS_CreateColorData( &R5G6B5_ColorData,         16, 0x0000f800, 0x000007e0, 0x0000001f, 0x00000000, 0, 0, FALSE ) ;
		NS_CreateColorData( &R5G5B5X1_ColorData,       16, 0x0000f800, 0x000007c0, 0x0000003e, 0x00000000, 0, 0, FALSE ) ;
		NS_CreateColorData( &X1R5G5B5_ColorData,       16, 0x00007c00, 0x000003e0, 0x0000001f, 0x00000000, 0, 0, FALSE ) ;
		NS_CreateColorData( &X8B8G8R8_ColorData,       32, 0x000000ff, 0x0000ff00, 0x00ff0000, 0x00000000, 0, 0, FALSE ) ;
		NS_CreateColorData( &X8R8G8B8_ColorData,       32, 0x00ff0000, 0x0000ff00, 0x000000ff, 0x00000000, 0, 0, FALSE ) ;
		InitializeFlag = TRUE ;
	}

	switch( PixelFormat )
	{
	case DX_USER_SCREEN_PIXEL_FORMAT_R5G6B5 :       return &R5G6B5_ColorData ;
	case DX_USER_SCREEN_PIXEL_FORMAT_R5G5B5X1 :     return &R5G5B5X1_ColorData ;
	case DX_USER_SCREEN_PIXEL_FORMAT_X1R5G5B5 :     return &X1R5G5B5_ColorData ;
	case DX_USER_SCREEN_PIXEL_FORMAT_X8B8G8R8 :     return &X8B8G8R8_ColorData ;
	case DX_USER_SCREEN_PIXEL_FORMAT_X8R8G8B8 :     return &X8R8G8B8_ColorData ;
	}
	return NULL ;
}

