// Jpeg_Quality         = 0:Åf?ÅÒ????`100:??ÅÒ???
// Png_CompressionLevel = 0:?????k?`  9:???????k
// ?????`ÅÒ?Åe???????????????ÅÒ???????ÅeÅ˜????
extern int SaveDrawScreen_WCHAR_T( int x1, int y1, int x2, int y2, const wchar_t *FileName, int SaveType, int Jpeg_Quality, int Jpeg_Sample2x1, int Png_CompressionLevel )
{
	BASEIMAGE BaseImage ;
	RECT      LockRect ;
	int       UseTempBaseImage = FALSE ;
	BASEIMAGE TempBaseImage ;
	BASEIMAGE *UseBaseImage ;

	// ?T?C?Y???s???????Åˆ??ÅÒ??????????I??
	if( x1 >= x2 || y1 >= y2 || x1 < 0 || y1 < 0 || x2 > GSYS.DrawSetting.DrawSizeX || y2 > GSYS.DrawSetting.DrawSizeY )
	{
		return -1 ;
	}

	// ?`ÅÒ????????b?N
	LockRect.left   = x1 ;
	LockRect.top    = y1 ;
	LockRect.right  = x2 ;
	LockRect.bottom = y2 ;
	if( Graphics_Screen_LockDrawScreen( &LockRect, &BaseImage, -1, -1, -1, TRUE, 0 ) < 0 )
	{
		return -1 ;
	}

	// ?C???[?W????ÅÒ?Åh?Åg]???????????Åˆ???Å}?Å}????ÅÒ?Åh?Åg]????
	_MEMSET( &TempBaseImage, 0, sizeof( TempBaseImage ) ) ;
	if( GSYS.HardInfo.MainScreenImageYReverse &&
		( ( DWORD )GSYS.DrawSetting.TargetScreen[ 0 ] == DX_SCREEN_BACK ||
		  ( DWORD )GSYS.DrawSetting.TargetScreen[ 0 ] == DX_SCREEN_FRONT ) )
	{
		UseTempBaseImage = TRUE ;
		NS_CreateColorDataBaseImage( BaseImage.Width, BaseImage.Height, &BaseImage.ColorData, &TempBaseImage ) ;
		NS_BltBaseImage2( 0, 0, &BaseImage, &TempBaseImage ) ;
		NS_ReverseBaseImageV( &TempBaseImage ) ;
		UseBaseImage = &TempBaseImage ;
	}
	else
	{
		UseBaseImage = &BaseImage ;
	}

	// ??ÅeÅ˜?`???????????????????X????
	switch( SaveType )
	{
	case DX_IMAGESAVETYPE_JPEG:
#ifndef DX_NON_JPEGREAD
		SaveBaseImageToJpeg_WCHAR_T( FileName, UseBaseImage, Jpeg_Quality, Jpeg_Sample2x1 );
#endif
		break;

	case DX_IMAGESAVETYPE_PNG:
#ifndef DX_NON_PNGREAD
		SaveBaseImageToPng_WCHAR_T( FileName, UseBaseImage, Png_CompressionLevel );
#endif
		break;

	case DX_IMAGESAVETYPE_BMP:	// Bitmap 
		SaveBaseImageToBmp_WCHAR_T( FileName, UseBaseImage ) ;
		break ;

	case DX_IMAGESAVETYPE_DDS:	// Direct Draw Surface
		SaveBaseImageToDds_WCHAR_T( FileName, UseBaseImage ) ;
		break ;
	}

	// ?`ÅÒ??????A?Åg???b?N
	Graphics_Screen_UnlockDrawScreen() ;

	// ?e?Åg?|?ÅÒ???C???[?W??ÅÒ???
	if( UseTempBaseImage )
	{
		NS_ReleaseBaseImage( &TempBaseImage ) ;
	}

	// ?I??
	return 0 ;
}

