extern int SaveDrawValidGraph_WCHAR_T( int GrHandle, int x1, int y1, int x2, int y2, const wchar_t *FileName, int SaveType, int Jpeg_Quality, int Jpeg_Sample2x1, int Png_CompressionLevel )
{
	IMAGEDATA *Image ;
	BASEIMAGE BaseImage ;
	RECT LockRect ;

	if( GRAPHCHKFULL( GrHandle, Image ) )
	{
		return -1 ;
	}

	// ?T?C?Y??ÅÒ??????????????A???? DDS ?t?@?C????????ÅeÅ˜???A?e?N?X?`???????Åˆ?????p?????????s??
	if( x1 == 0 && y1 == 0 && x2 == Image->WidthI && y2 == Image->HeightI &&
		SaveType == DX_IMAGESAVETYPE_DDS && Image->Orig->FormatDesc.TextureFlag == TRUE )
	{
		int CubeMapFlag ;
		int MipMapCount ;
		int ArraySize ;
		int BaseImageNum ;
		BASEIMAGE *BaseImageDim ;
		int i ;
		int j ;
		int k ;
		int Result ;

		CubeMapFlag = Image->Orig->FormatDesc.CubeMapTextureFlag ;
		ArraySize = CubeMapFlag ? CUBEMAP_SURFACE_NUM : 1 ;
		MipMapCount = Image->Orig->Hard.MipMapCount ;
		BaseImageNum = ArraySize * MipMapCount ;

		BaseImageDim = ( BASEIMAGE * )DXALLOC( sizeof( BASEIMAGE ) * BaseImageNum ) ;
		if( BaseImageDim == NULL )
		{
			DXST_LOGFILE_ADDUTF16LE( "\xcf\x63\x3b\x75\xfe\x5b\x61\x8c\x6b\x30\x67\x30\x4d\x30\x8b\x30\xb0\x30\xe9\x30\xd5\x30\xa3\x30\xc3\x30\xaf\x30\xcf\x30\xf3\x30\xc9\x30\xeb\x30\xdd\x4f\x58\x5b\xe6\x51\x06\x74\x67\x30\x7f\x4f\x28\x75\x59\x30\x8b\x30\x20\x00\x42\x00\x41\x00\x53\x00\x45\x00\x49\x00\x4d\x00\x41\x00\x47\x00\x45\x00\x20\x00\xcb\x69\x20\x90\x53\x4f\x4d\x91\x17\x52\x92\x30\xdd\x4f\x58\x5b\x59\x30\x8b\x30\x5f\x30\x81\x30\x6e\x30\xe1\x30\xe2\x30\xea\x30\x6e\x30\xba\x78\xdd\x4f\x6b\x30\x31\x59\x57\x65\x57\x30\x7e\x30\x57\x30\x5f\x30\x0a\x00\x00"/*@ L"?`ÅÒ?Åe????????????O?ÅÒ?t?B?b?N?n?Åg?h????ÅeÅ˜???????g?p???? BASEIMAGE ?\Åe?Åe?Åhz??????ÅeÅ˜???????????????????m??????Åhs????????\n" @*/ ) ;
			return -1 ;
		}
		_MEMSET( BaseImageDim, 0, sizeof( BASEIMAGE ) * BaseImageNum ) ;

		k = 0 ;
		for( i = 0 ; i < ArraySize ; i ++ )
		{
			for( j = 0 ; j < MipMapCount ; j ++, k ++ )
			{
				int Width, Height ;

				Graphics_Image_CalcMipSize( Image->WidthI, Image->HeightI, j, &Width, &Height ) ;

				// ?`ÅÒ?Åe????????????O?ÅÒ?t?B?b?N?n?Åg?h???????b?N
				LockRect.left   = 0 ;
				LockRect.top    = 0 ;
				LockRect.right  = Width ;
				LockRect.bottom = Height ;
				if( Graphics_Screen_LockDrawScreen( &LockRect, &BaseImage, GrHandle, i, j, TRUE, 0 ) < 0 )
				{
					DXFREE( BaseImageDim ) ;
					BaseImageDim = NULL ;

					for( i = 0 ; i < k ; i ++ )
					{
						NS_ReleaseBaseImage( &BaseImageDim[ i ] ) ;
					}

					return -1 ;
				}

				// ÅÒ?Åe???????
				if( NS_CreateColorDataBaseImage( BaseImage.Width, BaseImage.Height, &BaseImage.ColorData, &BaseImageDim[ k ] ) < 0 )
				{
					DXFREE( BaseImageDim ) ;
					BaseImageDim = NULL ;

					for( i = 0 ; i < k ; i ++ )
					{
						NS_ReleaseBaseImage( &BaseImageDim[ i ] ) ;
					}

					DXST_LOGFILE_ADDUTF16LE( "\xcf\x63\x3b\x75\xfe\x5b\x61\x8c\x6b\x30\x67\x30\x4d\x30\x8b\x30\xb0\x30\xe9\x30\xd5\x30\xa3\x30\xc3\x30\xaf\x30\xcf\x30\xf3\x30\xc9\x30\xeb\x30\xdd\x4f\x58\x5b\xe6\x51\x06\x74\x67\x30\x7f\x4f\x28\x75\x59\x30\x8b\x30\xe1\x30\xe2\x30\xea\x30\x6e\x30\xba\x78\xdd\x4f\x6b\x30\x31\x59\x57\x65\x57\x30\x7e\x30\x57\x30\x5f\x30\x0a\x00\x00"/*@ L"?`ÅÒ?Åe????????????O?ÅÒ?t?B?b?N?n?Åg?h????ÅeÅ˜???????g?p?????????????m??????Åhs????????\n" @*/ ) ;
					return -1 ;
				}
				BltBaseImage2( 0, 0, &BaseImage, &BaseImageDim[ k ] ) ;

				// ?`ÅÒ??????A?Åg???b?N
				Graphics_Screen_UnlockDrawScreen() ;
			}
		}

		// ?t?@?C??????ÅeÅ˜
		Result = SaveBaseImageToDds_WCHAR_T( FileName, BaseImageDim, CubeMapFlag, MipMapCount ) ;

		for( i = 0 ; i < k ; i ++ )
		{
			NS_ReleaseBaseImage( &BaseImageDim[ i ] ) ;
		}

		DXFREE( BaseImageDim ) ;
		BaseImageDim = NULL ;

		return Result ;
	}

	// ?T?C?Y???s???????Åˆ??ÅÒ??????????I??
	if( x1 >= x2 || y1 >= y2 || x1 < 0 || y1 < 0 || x2 > Image->WidthI || y2 > Image->HeightI )
	{
		return -1 ;
	}

	// ?`ÅÒ?Åe????????????O?ÅÒ?t?B?b?N?n?Åg?h???????b?N
	LockRect.left   = x1 ;
	LockRect.top    = y1 ;
	LockRect.right  = x2 ;
	LockRect.bottom = y2 ;
	if( Graphics_Screen_LockDrawScreen( &LockRect, &BaseImage, GrHandle, 0, 0, TRUE, 0 ) < 0 )
	{
		return -1 ;
	}

	// ??ÅeÅ˜?`???????????????????X????
	switch( SaveType )
	{
	case DX_IMAGESAVETYPE_JPEG:
#ifndef DX_NON_JPEGREAD
		SaveBaseImageToJpeg_WCHAR_T( FileName, &BaseImage, Jpeg_Quality, Jpeg_Sample2x1 );
#endif
		break;

	case DX_IMAGESAVETYPE_PNG:
#ifndef DX_NON_PNGREAD
		SaveBaseImageToPng_WCHAR_T( FileName, &BaseImage, Png_CompressionLevel );
#endif
		break;

	case DX_IMAGESAVETYPE_BMP:	// Bitmap 
		SaveBaseImageToBmp_WCHAR_T( FileName, &BaseImage ) ;
		break ;

	case DX_IMAGESAVETYPE_DDS:	// Direct Draw Surface
		SaveBaseImageToDds_WCHAR_T( FileName, &BaseImage ) ;
		break ;
	}

	// ?`ÅÒ??????A?Åg???b?N
	Graphics_Screen_UnlockDrawScreen() ;

	// ?I??
	return 0 ;
}

