#define SETDRAWRECTCODE\
	int MaxX, MaxY, MinX, MinY ;\
	int i, ix, iy, Num = Param->QuadrangleNum * 4 ;\
\
	MaxX = 0 ; MaxY = 0 ;\
	MinX = 0xfffffff ; MinY = 0xfffffff ;\
\
	for( i = 0 ; i < Num ; i ++ )\
