// ?C?Åg?f?b?N?X?o?b?t?@??????????
extern int Graphics_IndexBuffer_Create( int IndexNum, int IndexType /* DX_INDEX_TYPE_16BIT Åg? */, int ASyncThread )
{
	int NewHandle ;
	int Result ;

	// ?V?????n?Åg?h????????????
	NewHandle = AddHandle( DX_HANDLETYPE_INDEX_BUFFER, ASyncThread, -1 ) ;
	if( NewHandle < 0 )
	{
		return -1 ;
	}

	// ?n?Åg?h?????Z?b?g?A?b?v
	Result = Graphics_IndexBuffer_SetupHandle( NewHandle, IndexNum, IndexType ) ;
#ifndef DX_NON_ASYNCLOAD
	if( ASyncThread )
	{
		DecASyncLoadCount( NewHandle ) ;
	}
#endif // DX_NON_ASYNCLOAD
	if( Result < 0 )
	{
		SubHandle( NewHandle, FALSE, ASyncThread ) ;
		return -1 ;
	}

	// ?n?Åg?h????????
	return NewHandle ;
}

// ?C?Åg?f?b?N?X?o?b?t?@?n?Åg?h?????Z?b?g?A?b?v???s??
extern int Graphics_IndexBuffer_SetupHandle( int IndexBufHandle, int IndexNum, int IndexType /* DX_INDEX_TYPE_16BIT Åg? */ )
{
	INDEXBUFFERHANDLEDATA *IndexBuffer ;
	int IndexSize ;

	// ?G?ÅÒ?[Åh?Åf?
	if( INDEXBUFFERCHK( IndexBufHandle, IndexBuffer ) )
		return -1 ;

	// Åe?ÅÒ????????????^?C?v?????Åˆ???G?ÅÒ?[
	switch( IndexType )
	{
	case DX_INDEX_TYPE_16BIT :
		IndexSize = sizeof( WORD ) ;
		break ;

	case DX_INDEX_TYPE_32BIT :
		IndexSize = sizeof( DWORD ) ;
		break ;

	default :
		DXST_LOGFILE_ADDUTF16LE( "\xa4\x30\xf3\x30\xc7\x30\xc3\x30\xaf\x30\xb9\x30\xbf\x30\xa4\x30\xd7\x30\x6e\x30\x24\x50\x4c\x30\x0d\x4e\x63\x6b\x67\x30\x59\x30\x0a\x00\x00"/*@ L"?C?Åg?f?b?N?X?^?C?v??Åfl???s??????\n" @*/ ) ;
		return -1 ;
	}

	// ?^?C?v????ÅeÅ˜
	IndexBuffer->Type = IndexType ;

	// ?C?Åg?f?b?N?X?f?[?^???????????o?C?g?Åh????ÅeÅ˜
	IndexBuffer->UnitSize = IndexSize ;

	// ?C?Åg?f?b?N?X?Åh????ÅeÅ˜
	IndexBuffer->Num = IndexNum ;

	// ??????ÅeÅ˜???C?Åg?f?b?N?X?o?b?t?@????????
	if( Graphics_Hardware_IndexBuffer_Create_PF( IndexBuffer ) < 0 )
	{
		return -1 ;
	}

	// ?f?[?^???????m??????
	if( ReallocHandle( IndexBufHandle, sizeof( INDEXBUFFERHANDLEDATA ) + sizeof( INDEXBUFFERHANDLEDATA_PF ) + IndexSize * IndexNum + 32 ) < 0 )
	{
		DXST_LOGFILE_ADDUTF16LE( "\xe1\x30\xe2\x30\xea\x30\x6e\x30\xba\x78\xdd\x4f\x6b\x30\x31\x59\x57\x65\x57\x30\x7e\x30\x57\x30\x5f\x30\x00"/*@ L"?????????m??????Åhs????????" @*/ ) ;
		return -1 ;
	}
	IndexBuffer     = ( INDEXBUFFERHANDLEDATA *    )GetHandleInfo( IndexBufHandle ) ;
	IndexBuffer->PF = ( INDEXBUFFERHANDLEDATA_PF * )( IndexBuffer + 1 ) ;

	// ?V?X?e?????????????C?Åg?f?b?N?X?f?[?^????ÅeÅ˜?????A?h???X???Z?b?g
	IndexBuffer->Buffer = ( void * )( ( ( DWORD_PTR )IndexBuffer + sizeof( INDEXBUFFERHANDLEDATA ) + sizeof( INDEXBUFFERHANDLEDATA_PF ) + 31 ) / 32 * 32 ) ;

	// ?????I??
	return 0 ;
}

